    Mappings diffMappings = new Mappings();

    // Iterate through the fields in the input mappings
    for (String fieldName : mappings.getFields()) {
        // Check if the field exists in the current index
        if (!mappings.getFields().contains(fieldName)) {
            // Add the field to the diffMappings object
            diffMappings.addField(fieldName);
        }
    }

    // Return the diffMappings object
    return diffMappings;
}
