public long readLong(final int offset) {
    // Check if the offset is within the valid range
    if (offset < 0 || offset >= this.data.length) {
        throw new IllegalArgumentException("Offset out of bounds");
    }

    // Read the long value from the data array
    long value = this.data[offset] & 0xFF;
    value |= (this.data[offset + 1] & 0xFF) << 8;
    value |= (this.data[offset + 2] & 0xFF) << 16;
    value |= (this.data[offset + 3] & 0xFF) << 24;

    return value;
}
